/* Neon scene adapter. Positions, operators, status lights and desks are live DOM layers.
   The environmental plate contains no agents, controls or central workstations. */
window.WorkshopHeadquarters = (() => {
  const variants={round:0,square:1,cat:2};
  const labels={idle:'Idle',queued:'Queued',working:'Working', 'using-tool':'Using tool',paused:'Waiting · paused',completed:'Completed',failed:'Failed',cancelled:'Cancelled'};
  function operator(a){
    const variant=variants[a.avatar]??0;
    return `<span class="bot neon-avatar operator-sprite operator-${variant}" aria-hidden="true"><span class="operator-figure"></span><span class="operator-pin">${['✿','◆','★','☀','☾','✦','♥'].includes(a.symbol)?a.symbol:'✿'}</span></span>`;
  }
  function desk(slotId){return `<svg class="hq-desk" viewBox="0 0 300 160" aria-hidden="true"><defs><linearGradient id="desk-top-${slotId}" x2="0.4" y2="1"><stop stop-color="#3a3737"/><stop offset="1" stop-color="#18181c"/></linearGradient></defs><ellipse cx="154" cy="145" rx="136" ry="13" fill="#000" opacity=".45"/><path d="m23 88 7 58 19-2 5-55m191-2 9 57 19-3 2-52" fill="#131317" stroke="#42404b"/><path d="m20 65 238-8 32 32-282 8Z" fill="url(#desk-top-${slotId})" stroke="#68616b"/><path d="m8 97 282-8v13L8 113Z" fill="#111014" stroke="#3c3743"/><path class="desk-rim" d="m17 105 262-8" stroke="var(--agent)" stroke-width="2"/><path d="m29 114 7 24 228-7 4-24" fill="#17161b" stroke="#35303e"/><path d="m42 118 58-2m89-2 58-2" stroke="#4a424d"/><path d="m101 83 61-3 13 9-80 3Z" fill="#29252e" stroke="#5e5264"/><path class="keyboard-glow" d="m103 85 49-2m-45 5 56-2" stroke="var(--agent)" opacity=".65"/><g class="monitor"><path d="m177 19 74-4-5 53-70 3Z" fill="#0a0c11" stroke="#7e6a80" stroke-width="2"/><path d="m182 24 63-4-4 43-60 3Z" fill="var(--agent)" opacity=".13"/><path class="screen-lines" d="m188 31 43-2m-44 9 30-1m-30 9 47-3m-48 10 26-1" stroke="var(--agent)" stroke-width="2"/><path d="m210 70-1 9m-13 2 29-2" stroke="#6a606e" stroke-width="3"/></g><path d="M40 73 50 40 64 28" stroke="#71626a" stroke-width="3" fill="none"/><path d="m54 26 20-7 10 12-32 6Z" fill="#292126" stroke="#a2764f"/><path d="m54 37 24-5" stroke="#ffcf91" stroke-width="3"/><path d="m37 69 30-1-2 6-25 1Z" fill="#3a3037"/><path d="m269 63 10-1 1 18-12 1Z" fill="#5e4646"/><path d="M272 63v-20m1 8-7-5m7 10 8-7" stroke="#799274" stroke-width="3"/><circle class="hardware-led" cx="260" cy="119" r="2.5" fill="var(--agent)"/></svg>`;}
  function slot(index){
    const row=Math.floor(index/3),column=index%3;
    return {x:[375,630,885][column]+(row%2?14:0),y:row===0?505:695+(row-1)*205,scale:row===0?.85:1,row};
  }
  function scene(agents,selected,statusOf,esc,zoom){
    const count=Math.max(6,agents.length),height=Math.max(800,800+(Math.ceil(count/3)-2)*205);
    const working=agents.filter(a=>['working','using-tool'].includes(statusOf(a.id))).length;
    return `<div class="shared-room headquarters" aria-label="Interactive shared Neon headquarters"><div class="hq-toolbar"><div><span class="eyebrow">NOCTURNE / OPERATIONS FLOOR</span><span class="hq-live">${agents.length} agents present · ${working} working</span></div><button class="small" data-scene-console>Open task console ↓</button></div><div class="room-scroll" tabindex="0" aria-label="Scrollable headquarters. Select an operator or use the agent selector."><div class="room-world hq-world" style="zoom:${zoom};width:1200px;min-width:1200px;height:${height}px"><div class="hq-architecture" aria-hidden="true"></div><div class="hq-window-rain" aria-hidden="true"></div><div class="studio-sign hq-sign">NOCTURNE<small>RESEARCH HEADQUARTERS</small></div><div class="hq-floor-extension" style="height:${Math.max(0,height-800)}px" aria-hidden="true"></div><div class="hq-walkway" aria-hidden="true"></div><div class="station-grid hq-stations" style="--columns:3">${Array.from({length:count},(_,i)=>{
      const a=agents[i],p=slot(i),position=`left:${p.x}px;top:${p.y}px;--depth:${p.scale};z-index:${p.row+2}`;
      if(!a)return `<button class="vacant-station" data-action="new-agent" style="${position};--agent:#686574" aria-label="Create an agent for available workstation ${i+1}"><span class="empty-chair" aria-hidden="true"></span>${desk(i)}<span class="vacant-label">＋ Available station</span></button>`;
      const state=statusOf(a.id),label=labels[state]||'Idle';
      return `<button class="station hq-station ${state} ${a.id===selected?'selected':''}" data-select-agent="${a.id}" data-agent-name="${esc(a.name)}" data-wire-x="${p.x}" data-wire-y="${p.y-103*p.scale}" style="${position};${WorkshopIdentity.style(a)}" aria-pressed="${a.id===selected}" aria-label="Select ${esc(a.name)}, ${label}"><span class="station-shadow" aria-hidden="true"></span><span class="operator-chair" aria-hidden="true"></span><span class="station-figure">${operator(a)}</span>${desk(i)}<span class="selection-marker">${a.id===selected?'Selected operator':'Select operator'}</span><span class="station-name"><b>${a.symbol}</b> ${esc(a.name)}</span><span class="station-role">${esc(a.role)}</span><span class="station-status"><span class="status-dot"></span>${label}</span><span class="station-progress" aria-hidden="true"><i></i></span></button>`;
    }).join('')}</div><div class="hq-foreground" aria-hidden="true"></div><div class="room-bottom">Simulation · live task and handoff records <span>Choose an operator to open their conversation.</span></div></div></div></div>`;
  }
  return {operator,scene,slot};
})();
